-- HOLIDAYS · Halloween · Halloween · 7–9 · beginners
do $mig$
declare
  v_course uuid; v_unit uuid; v_lesson uuid;
  v_media text := 'https://classroom.wowteach.ru/media/';
begin
  select id into v_course from classroom_courses where slug = 'holidays';
  if v_course is null then raise exception 'course holidays not found'; end if;

  select id into v_unit from classroom_units
   where course_id = v_course and title = 'Halloween' limit 1;
  if v_unit is null then
    insert into classroom_units (course_id, title, sort_order)
    values (v_course, 'Halloween', 1) returning id into v_unit;
  end if;

  select id into v_lesson from classroom_lessons
   where unit_id = v_unit and title = 'Halloween · 7–9 · beginners' limit 1;
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, summary, sort_order, is_published, pass_threshold, kind)
    values (v_unit, 'Halloween · 7–9 · beginners', 'Урок-игра для 7–9 лет, начинающие', 1, false, 60, 'lesson')
    returning id into v_lesson;
  else
    update classroom_lessons set summary = 'Урок-игра для 7–9 лет, начинающие', sort_order = 1,
           is_published = false, pass_threshold = 60, kind = 'lesson'
     where id = v_lesson;
  end if;

  insert into classroom_blocks (lesson_id, type, payload, sort_order) values
    -- блок 1 (sort_order 0) · интерактивный урок
    (v_lesson, 'embed', replace($blk${"url": "https://classroom.wowteach.ru/lessons/halloween/7-9_beginners.html"}$blk$, '@@MEDIA@@', v_media)::jsonb, 0),
    -- блок 2 (sort_order 1) · как провести — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<div style=\"padding:16px 18px;background:#fff7ec;border-radius:14px;border:2px solid #f3d3a3\">\n<h3 style=\"margin:0 0 6px;color:#8a3c08\">🎃 Как провести урок</h3>\n<p style=\"margin:0 0 8px\">«Планы уроков» → этот урок → <b>«▶ Показ»</b>: урок откроется на весь экран. Демонстрируйте в Zoom <b>эту вкладку</b>, а не весь экран.</p>\n<p style=\"margin:0 0 8px\">План урока — кнопка 📋 вверху справа внутри урока (откроется отдельным окном) или ниже на этой странице.</p>\n<p style=\"margin:0\">Если удобнее отдельной вкладкой: <a href=\"https://classroom.wowteach.ru/lessons/halloween/7-9_beginners.html\">открыть урок</a>. Нужен интернет: картинки и музыка загружаются с сервера.</p></div>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 1),
    -- блок 3 (sort_order 2) · план — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<h3>План урока</h3><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>Длительность:</b> 35–40 мин. &nbsp; <b>Мотивация:</b> украшаем комнату к Хэллоуину — за каждую игру новое украшение, в конце фото.</div><table style=\"width:100%;border-collapse:collapse;font-size:14px\"><tr><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Стр.</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Задание и инструкция</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Teacher's language</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Suggested answers / Students' answers</th></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">1</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Warm-up.</b> Картинка хэллоуинской улицы. На экране ничего не написано — вопросы задаёт учитель.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What can you see?\" \"What colour is the cat?\" \"What holiday is it?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"I can see a cat / a witch / bats.\" \"It's black.\" \"It's Halloween!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">2</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Новые слова</b> (6). Появляется картинка — учитель называет слово, ученик повторяет. Следующее слово — Next или нажатие на картинку.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Look! It's a witch. Say: witch!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Witch!\" \"It's a witch.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">3</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Комната.</b> Пустая комната. Прилетает привидение Boo и просит помочь украсить комнату к вечеринке. За каждую игру в комнате появляется украшение.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"This is the room. Is it nice? Let's decorate it for Halloween!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Yes!\" \"OK!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">4</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Волшебный туман (6 раундов — все слова).</b> Туман медленно рассеивается, ученик угадывает как можно раньше. Угадал — нажмите на картинку или 👀. После игры загорается Next — откроется комната, новое украшение подсветится. Спросите «What's new?». Кружочки вверху — раунды.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What's this?\" \"Is it a bat?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"It's a spider!\" \"Yes, it is. / No, it isn't.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">5</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Knock, knock! (6 дверей — все слова).</b> Двери разных цветов, без номеров: ученик выбирает дверь по цвету, учитель нажимает — персонаж выпрыгивает. Подписей нет: ученик сам называет его. После игры загорается Next — откроется комната, новое украшение подсветится. Спросите «What's new?». Кружочки вверху — раунды.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Which door?\" \"Knock, knock! Who's there?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"The pink door!\" \"It's a witch!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">6</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Фонарик (3 раунда).</b> Экран тёмный, картинки спрятаны. Учитель водит фонарик мышкой, ученик говорит, куда светить. Нашли — нажмите на картинку. Вверху написано, что искать. После игры загорается Next — откроется комната, новое украшение подсветится. Спросите «What's new?». Кружочки вверху — раунды.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Find the witch! Left or right? Up or down?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Left! Up!\" \"Here! It's the witch!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">7</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Peekaboo (6 раундов — все персонажи).</b> Персонаж прячется в комнате: за шкафом, под кроватью, за дверью, в окне. Видно только кусочек — ученик угадывает. Нажмите на персонажа или 👀. После игры загорается Next — откроется комната, новое украшение подсветится. Спросите «What's new?». Кружочки вверху — раунды.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Who's hiding?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"It's a ghost!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">8</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Найди отличия (5).</b> Две картинки. Ученик ищет отличия, учитель нажимает на найденное (на любой картинке) — отличие обводится на обеих. После игры загорается Next — откроется комната, новое украшение подсветится. Спросите «What's new?». Кружочки вверху — раунды.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Look! What's different?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"A green pumpkin!\" \"Two bats!\" \"A big ghost!\" \"A monster!\" \"The cat!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">9</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Собери монстра (3 раунда + свой монстр).</b> Вверху задание. Ученик собирает монстра кнопками: цвет, глаза, руки, ноги, рога. ✓ — проверить. В конце ученик собирает своего монстра.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Make a blue monster with three eyes!\" \"How many eyes?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Blue! One, two, three eyes!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">10</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Анаграмма (6 слов).</b> Картинка-подсказка и перепутанные буквы. Ученик называет буквы по порядку, учитель нажимает. <b>Если ученик ещё не читает</b> — пусть просто назовёт слово по картинке, а учитель соберёт его кнопкой Next (одна буква за нажатие). После игры загорается Next — откроется комната, новое украшение подсветится. Спросите «What's new?». Кружочки вверху — раунды.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What's this? Spell it! What letter is first?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Bat! B-A-T.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">11</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>I like / I don't like (6 карточек — все слова).</b> Ученик отвечает, учитель нажимает 👍 или 👎. Конфета даётся за любой ответ. После игры загорается Next — откроется комната, новое украшение подсветится. Спросите «What's new?». Кружочки вверху — раунды.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Do you like spiders?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"I like spiders!\" \"I don't like spiders.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">12</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Настольная игра «Дом с привидениями».</b> Выберите от 1 до 5 фишек (ученики и учитель) и подпишите имена под фишками, потом ▶. Кидаем кубик (🎲 или Next), фишка идёт сама. На клетке с картинкой — назвать её. ⭐ — показать действие, ⏩ — вперёд на 2, ⏪ — назад на 2. Кто первым дойдёт до дома — победил. После игры загорается Next — откроется комната, новое украшение подсветится. Спросите «What's new?». Кружочки вверху — раунды.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Roll the dice!\" \"What is it?\" \"Your turn!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"It's a ghost!\" \"Six!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">13</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Бонусные игры (если есть время).</b> Можно сыграть во все или сразу нажать Finish 🏁. После игры — 🎁: в комнате новое украшение, «🎮 ←» — назад к списку игр.<br>• <b>Dance</b>: сначала 4 карточки — учитель показывает движение, ученик повторяет. ▶ — музыка, скелет танцует, ученик тоже; музыка остановилась — появляется картинка, ученик показывает движение.<br>• <b>Memory</b>: пары «картинка — картинка», ученик называет слово.<br>• <b>Shadows</b>: найти тень (4 раунда).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Let's dance!\" \"Stop! What is it? Show me!\" \"Find the pairs!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"A bat!\" \"A ghost! Boo!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">14</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Подарок за конфеты.</b> Вверху — сколько конфет собрал ученик (🍬 падает за каждый правильный ответ). Сколько бы ни собрал — выбирает один подарок в комнату: котёл, шарики или подарки. Новое украшение подсветится.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"You've got 25 candies! Well done! A cauldron, balloons or presents?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Balloons, please!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">15</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Вечеринка Boo.</b> Привидение Boo благодарит за помощь, гости танцуют. Спросите, кого ученик видит на вечеринке.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Look! Who is at the party?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"A witch! A vampire! A skeleton!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">16</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Финал.</b> Фото комнаты с выбранным подарком. «Save photo» — скачать и отправить родителям. ← — назад.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Look at your room! Happy Halloween!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Happy Halloween!\" \"Thank you!\"</td></tr></table><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>🗂️ Лексика и грамматика:</b> ghost, bat, spider, witch, pumpkin, skeleton • colours • numbers 1–10 • It's a… / I can see… • I like / I don't like</div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0;font-size:13px;color:#777\"><b>Навигация:</b> ← → — назад / пропустить; Next загорается, когда задание выполнено, а в играх с раундами ведёт к следующему раунду. 📋 — этот план, 🎵 — музыка. Кружочки страниц вверху слева кликабельны — можно сразу перейти на любую страницу. 🍬 вверху справа — копилка: за каждый правильный ответ ученику падает конфета.</div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>🏠 Домашнее задание</b> — материал <b>«Halloween Homework · 7–9 · beginners»</b> на платформе: «Материалы» → «Задать ДЗ» → ученик → отметить. Только слова урока, 10–15 минут. Задания:<ol style=\"margin:6px 0 0 22px\"><li>Карточки со звуком</li><li>🎤 Повтори слова</li><li>Послушай и выбери картинку</li><li>Найди одинаковые картинки</li><li>Соедини слово и картинку</li><li>🎤 Назови, что видишь на картинке</li></ol><div style=\"color:#777;font-size:13px;margin-top:4px\">Устные задания ученик записывает голосом — их вы слушаете и оцениваете в «Проверке ДЗ».</div></div>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 2),
    -- блок 4 (sort_order 3) · ДЗ — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<h3>Домашнее задание</h3><p>Материал <b>«Halloween Homework · 7–9 · beginners»</b> в этом же юните. «Материалы» → «Задать ДЗ» → ученик → отметить.</p>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 3)
  on conflict (lesson_id, sort_order) do update
    set type = excluded.type, payload = excluded.payload;

  delete from classroom_blocks where lesson_id = v_lesson and sort_order >= 4;
  update classroom_blocks set audience = 'shared' where lesson_id = v_lesson and sort_order = 0;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 1;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 2;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 3;
end
$mig$;
